template:
% 参数由系统自动注入；三棱锥 P-ABC：ABC 为底面三角形，P 为顶点
% D 在棱 PB 上(dpar)，E 在棱 PA 上(epar)，F 在底边 AC 上(fpar)，O 在线段 BF 上(opar)
% 实线：侧棱 PA/PB/PC、底边 AB/AC、辅助线 AD、EF
% 虚线：底边 BC(遮挡)、BF、PO、DO、AO
% 视觉归一化：把图形最长外接尺寸缩放到 6 个坐标单位，线宽与虚线样式不缩放

% ==========================================================
% 三棱锥透视参数
% ==========================================================
% 底面 ABC：B、C 位于同一水平线，A 位于底面前方偏左
% P 位于 BC 中点正上方

\pgfmathsetmacro{\bx}{-2.5 * \side}
\pgfmathsetmacro{\by}{0}
\pgfmathsetmacro{\cx}{2.5 * \side}
\pgfmathsetmacro{\cy}{0}
\pgfmathsetmacro{\ax}{-0.9 * \side}
\pgfmathsetmacro{\ay}{-1.2 * \side}
\pgfmathsetmacro{\px}{0}
\pgfmathsetmacro{\py}{2.6 * \side}

% 视觉归一化
\pgfmathsetmacro{\figscale}{6 / max(\cx - \bx, \py - \ay)}

% ==========================================================
% 开始绘图
% ==========================================================
\begin{tikzpicture}[
    scale=\figscale,
    every node/.style={
        font=\small,
        fill=none,
        inner sep=1.5pt
    }
]

    % 三棱锥四个顶点
    \coordinate (A) at (\ax,\ay);
    \coordinate (B) at (\bx,\by);
    \coordinate (C) at (\cx,\cy);
    \coordinate (P) at (\px,\py);

    % 基本三棱锥结构
    % 侧棱 PA、PB、PC
    \draw[thick] (P) -- (A);
    \draw[thick] (P) -- (B);
    \draw[thick] (P) -- (C);

    % 底面边 AB、AC 实线；BC 被遮挡用虚线
    \draw[thick] (A) -- (B);
    \draw[thick] (A) -- (C);
    \draw[dashed,thick] (B) -- (C);

    % ======================================================
    % 条件性绘制辅助元素
    % ======================================================
    \ifnum\showaux>0
        % D 在 PB 上
        \pgfmathsetmacro{\Dx}{\bx + \dpar * (\px - \bx)}
        \pgfmathsetmacro{\Dy}{\by + \dpar * (\py - \by)}
        \coordinate (D) at (\Dx,\Dy);

        % E 在 PA 上
        \pgfmathsetmacro{\Ex}{\ax + \epar * (\px - \ax)}
        \pgfmathsetmacro{\Ey}{\ay + \epar * (\py - \ay)}
        \coordinate (E) at (\Ex,\Ey);

        % F 在 AC 上
        \pgfmathsetmacro{\Fx}{\ax + \fpar * (\cx - \ax)}
        \pgfmathsetmacro{\Fy}{\ay + \fpar * (\cy - \ay)}
        \coordinate (F) at (\Fx,\Fy);

        % O 在线段 BF 上
        \pgfmathsetmacro{\Ox}{\bx + \opar * (\Fx - \bx)}
        \pgfmathsetmacro{\Oy}{\by + \opar * (\Fy - \by)}
        \coordinate (O) at (\Ox,\Oy);

        % 辅助线
        \draw[dashed,thick] (B) -- (F);   % 底面线段 BF
        \draw[dashed,thick] (P) -- (O);
        \draw[dashed,thick] (D) -- (O);
        \draw[dashed,thick] (A) -- (O);
        \draw[thick] (D) -- (A);          % 侧面辅助线 AD
        \draw[thick] (E) -- (F);          % 侧面辅助线 EF（过 O）
    \fi

    % ======================================================
    % 顶点标签
    % ======================================================
    \ifnum\showverts>0
        \node[below left=4pt] at (B) {$B$};
        \node[right=5pt] at (C) {$C$};
        \node[below=5pt] at (A) {$A$};
        \node[above=4pt] at (P) {$P$};
        % 仅当辅助元素被启用时才显示辅助点标签
        \ifnum\showaux>0
            \node[left=5pt] at (D) {$D$};
            \node[right=3pt] at (E) {$E$};
            \node[below right=5pt] at (F) {$F$};
            \node[above=3pt] at (O) {$O$};
        \fi
    \fi

    % ======================================================
    % 辅助点
    % ======================================================
    \ifnum\showpoints>0
        % 仅当辅助元素被启用时才显示辅助点
        \ifnum\showaux>0
            \fill (D) circle [radius=1.6pt];
            \fill (E) circle [radius=1.6pt];
            \fill (F) circle [radius=1.6pt];
            \fill (O) circle [radius=1.6pt];
        \fi
    \fi

% ==========================================================
% 结束绘图
% ==========================================================
\end{tikzpicture}
